const input = $input.first()?.json ?? {};
const body = input.body ?? input;

return [{
  json: {
    config: {
      companyName: body.companyName || 'ABM Solutions Demo',
      senderName: body.senderName || 'Jordan Lee',
      senderEmail: body.senderEmail || 'demo@example.com',
      slackWebhookUrl: body.slackWebhookUrl || 'REPLACE_WITH_SLACK_WEBHOOK_URL',
      hubspotToken: body.hubspotToken || 'REPLACE_WITH_HUBSPOT_PRIVATE_APP_TOKEN',
      openAiApiKey: body.openAiApiKey || 'REPLACE_WITH_OPENAI_API_KEY',
      demoMode: body.demoMode !== false
    },
    payload: body
  }
}];

const root=$input.first().json,p=root.payload||{};
const text=p.text||`The operations team reviewed the lead handoff process. Sales currently copies form submissions into the CRM manually, then alerts account executives in Slack. Average response time is four hours. The team agreed to automate validation, CRM creation, ownership assignment, and alerts. Security requested that API tokens be stored in credentials. The pilot should launch next Friday, with Morgan responsible for testing and Jordan Lee responsible for documentation.`;
return [{json:{...root,document:{title:p.title||'Operations Meeting Notes',text}}}];

const d=$input.first().json, text=d.document.text;
const sentences=text.split(/(?<=[.!?])\s+/).filter(Boolean);
const actionWords=/agreed|should|will|responsible|launch|test|document|follow up/i;
const riskWords=/risk|security|delay|blocked|issue|concern/i;
const actions=sentences.filter(s=>actionWords.test(s)).slice(0,5);
const risks=sentences.filter(s=>riskWords.test(s)).slice(0,5);
const summary=sentences.slice(0,3).join(' ');
return [{json:{...d,result:{title:d.document.title,executiveSummary:summary,keyPoints:sentences.slice(0,6),actionItems:actions,risks,wordCount:text.trim().split(/\s+/).length}}}];
